// src/components/AdminExtraCurricular.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import ReactQuill from "react-quill";
import 'react-quill/dist/quill.snow.css';
import "../styles/main.css";

export default function AdminExtraCurricular() {
  const [content, setContent] = useState({
    foreignLanguages: "",
    ethics: "",
    sports: "",
    musicDance: "",
    artCraft: "",
    tourTrips: "",
  });

  const [loading, setLoading] = useState(true);

  // Fetch current content from backend
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/extracurricular")
      .then((res) => {
        if (res.data.success) {
          setContent(res.data.data);
        }
      })
      .catch((err) => toast.error("Failed to fetch content"))
      .finally(() => setLoading(false));
  }, []);

  // Handle quill editor change
  const handleChange = (field, value) => {
    setContent((prev) => ({ ...prev, [field]: value }));
  };

  // Save updates to backend
  const saveChanges = async () => {
    try {
      const res = await axios.post("http://localhost:5000/api/extracurricular", content);
      if (res.data.success) toast.success("Content updated successfully!");
      else toast.error("Failed to update content");
    } catch (err) {
      console.error(err);
      toast.error("Error saving changes");
    }
  };

  if (loading) return <p>Loading...</p>;

  return (
    <div className="admin-extra-page">
      <Toaster />
      <h2>🎨 Manage Extra Curricular Sections</h2>
      <p>Edit each section below and click "Save Changes" to update.</p>

      {Object.keys(content).map((key) => (
        <div key={key} className="editor-section">
          <h3>{formatTitle(key)}</h3>
          <ReactQuill
            theme="snow"
            value={content[key]}
            onChange={(value) => handleChange(key, value)}
            style={{ height: "200px", marginBottom: "20px" }}
          />
        </div>
      ))}

      <button onClick={saveChanges} className="save-btn">
        💾 Save Changes
      </button>
    </div>
  );
}

// Utility function to convert keys to readable titles
function formatTitle(key) {
  switch (key) {
    case "foreignLanguages": return "Foreign Languages";
    case "ethics": return "Ethics & Personality Development";
    case "sports": return "Sports";
    case "musicDance": return "Music & Dance";
    case "artCraft": return "Art & Craft";
    case "tourTrips": return "Tour & Trips";
    default: return key;
  }
}
